cd /tmp && d=$(ls -d /tmp/new/db/removed_data/20261008210500_remove_proposals_from_custom_pages* | tail -1); psql -h /var/lib/postgresql/sockets -U consul consul_smoke -At -c "\copy (select t.id, p.slug, t.locale, t.content from site_customization_page_translations t join site_customization_pages p on p.id = t.site_customization_page_id) to '/tmp/new_pages.csv' with (format csv, header)" && python3 - "$d/site_customization_page_translations.csv" <<'EOF'
import csv, sys, difflib, collections
csv.field_size_limit(10**9)
old = {r["id"]: r for r in csv.DictReader(open(sys.argv[1], encoding="utf-8"))}
new = {r["id"]: r for r in csv.DictReader(open("/tmp/new_pages.csv", encoding="utf-8"))}
removed_by = collections.defaultdict(list)
problems = 0
for id, o in old.items():
    n = new[id]
    sm = difflib.SequenceMatcher(None, o["content"], n["content"], autojunk=False)
    ops = [op for op in sm.get_opcodes() if op[0] != "equal"]
    if any(op[0] != "delete" for op in ops):
        problems += 1; print("NOT ONLY DELETIONS", id, n["slug"], n["locale"], ops)
    dels = [o["content"][a:b] for (t, a, b, c, d) in ops]
    removed_by[n["slug"]].append((n["locale"], dels))
for slug, items in sorted(removed_by.items()):
    print("==", slug, len(items))
    for locale, dels in sorted(items)[:40]:
        if locale in ("en", "es", "eu", "fa", "ne", "sl", "ca", "he") or slug != "accessibility" and locale in ("en","es","de"):
            print("  ", locale, [d.replace("\n", "\\n") for d in dels])
print("problems:", problems)
EOF

