import re
def section(path, start):
    lines = open(path).read().split("\n")
    out, on = {}, False
    for l in lines:
        if l.startswith("== "): on = l.startswith(start)
        elif on and l.strip():
            m = re.match(r"  (.{45}) (.*)", l)
            if m: out[m.group(1).strip()] = m.group(2)
    return out
b_before = section("/tmp/simB.out", "== pages before")
b_after = dict(b_before); b_after.update(section("/tmp/simB.out", "== pages after"))
c = section("/tmp/simC.out", "== pages before")
diff = {k: (b_after.get(k), v) for k, v in c.items() if b_after.get(k) != v}
print("deploy 3 code vs deploy 2 code, after the migration:", diff or "same answers on every page", len(c), "pages")
EOF

